// Exercise mz_adler32 with both NULL (initializer) and non-NULL buffer paths.
// Generate a random buffer (1..4096 bytes)
std::string buf = FUZZ_PARAM_STR();
// Randomly decide whether to request the initial value (ptr == NULL)
bool use_null = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
// Start value: either a random prior adler or the initializer path
mz_ulong adler_start = use_null ? 0 : (mz_ulong)(*FUZZ_PARAM(unsigned int));
// If use_null, mz_adler32 returns the initial value regardless of buf_len
mz_ulong a0 = mz_adler32(adler_start, use_null ? (const unsigned char*)NULL : (const unsigned char*)buf.data(), use_null ? (size_t)0 : (size_t)buf.size());
// Continue the stream with real data to exercise update path as well
mz_ulong a1 = mz_adler32(a0, (const unsigned char*)buf.data(), (size_t)buf.size());
(void)a1; // suppress unused warning
// Validation: ptr==NULL path covered; non-NULL path covered with readable buffer.

// Exercise mz_crc32 with both NULL (initializer) and non-NULL buffer paths.
std::string buf = FUZZ_PARAM_STR();
bool use_null = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
