memset(stream, 0, sizeof(*stream));
// Choose a valid compression level in [0,9] (miniz accepts zlib-compatible levels)
int level = (int)(*FUZZ_PARAM(unsigned int) % 10u); // 0..9
int st = mz_deflateInit(stream, level);
if (st != 0) { // non-OK => bail so downstream never sees a half-inited stream
    delete stream;
    FUZZ_BAIL();
}
// Track role and lifetime attributes for downstream stubs
