int method = 8; // MZ_DEFLATED
int window_bits = ((*FUZZ_PARAM(unsigned int)) & 1u) ? 15 : -15; // ±MZ_DEFAULT_WINDOW_BITS
int mem_level = 1 + (int)(*FUZZ_PARAM(unsigned int) % 9u);
int strategy = (int)(*FUZZ_PARAM(unsigned int) % 5u); // assume valid strategies map 0..4
int st = mz_deflateInit2(stream, level, method, window_bits, mem_level, strategy);
if (st != 0) {
